example.code:
// Apply a concert hall reverb preset to an audio effect.
// audioEffect.ReverbPreset = DSI3DL2ReverbPreset.Concerthall;

// Switch to a cave preset.
// audioEffect.ReverbPreset = DSI3DL2ReverbPreset.Cave;

// Create a new audio frame
var audioFrame = new AudioFrame();

// Populate its properties
audioFrame.Data = ...; // Pointer to raw audio data
audioFrame.DataSize = ...; // Size of the data in bytes
audioFrame.Timestamp = TimeSpan.FromSeconds(1.0);
audioFrame.Duration = TimeSpan.FromMilliseconds(40);
audioFrame.Info = new RAWBaseAudioInfo { Channels = 2, SampleRate = 44100, Format = AudioFormat.PCM16 };

// Process the frame
ProcessAudio(audioFrame);

// Create and populate a data frame
var dataFrame = new DataFrame();
try
{
    byte[] myData = new byte[] { 0x01, 0x02, 0x03, 0x04 };
    dataFrame.Alloc(myData.Length);
    System.Runtime.InteropServices.Marshal.Copy(myData, 0, dataFrame.Data, myData.Length);

    dataFrame.Timestamp = TimeSpan.FromSeconds(5);
    dataFrame.DataType = "CustomMetadata";

    // Use the frame
    ProcessCustomData(dataFrame);
}
finally
{
    // Ensure memory is always freed
    dataFrame.Free();
}

