// Assume an event handler is registered for a face detection event.
public void OnFaceDetection(object sender, AFFaceDetectionEventArgs e)
{
    Console.WriteLine($"Faces detected: {e.FaceRectangles.Length}");

    foreach (var rect in e.FaceRectangles)
    {
        #if NET_WINDOWS
        Console.WriteLine($"  Face at: X={rect.X}, Y={rect.Y}, Width={rect.Width}, Height={rect.Height}");
        #else
        Console.WriteLine($"  Face at: Left={rect.Left}, Top={rect.Top}, Right={rect.Right}, Bottom={rect.Bottom}");
        #endif
    }

    // If you modify the frame data (e.g., draw on it), set UpdateData to true.
    // e.UpdateData = true;
}

