// Example of tracking playback history
private List<string> playbackHistory = new List<string>();

player.OnNewFileStarted += (sender, e) =>
{
    // Add to history
    playbackHistory.Add(e.Filename);

    // Save last played position for previous file
    if (playbackHistory.Count > 1)
    {
        var previousFile = playbackHistory[playbackHistory.Count - 2];
        SavePlaybackPosition(previousFile);
    }

    // Load saved position for new file
    var savedPosition = LoadPlaybackPosition(e.Filename);
    if (savedPosition > 0)
    {
        player.Position_Set_Time(savedPosition);
    }
};

// Example of implementing exclusive camera access
private string currentCameraPath = null;

captureDevice.OnDeviceCanStart += (sender, e) =>
{
    // Check if this is a camera device
    if (e.DeviceName.Contains("Camera") || e.DeviceName.Contains("Webcam"))
    {
        // Allow only one camera at a time
        if (currentCameraPath == null || currentCameraPath == e.DevicePath)
        {
            e.CanStart = true;
            currentCameraPath = e.DevicePath;
        }
        else
        {
            e.CanStart = false;
            MessageBox.Show($"Camera {currentCameraPath} is already in use. Please stop it first.");
        }
    }
    else
    {
        // Allow all non-camera devices
        e.CanStart = true;
    }
};

