public async Task ManageCapture(IVideoCaptureControls capture)
{
    if (await capture.StartAsync())
    {
        Console.WriteLine("Capture started. Capturing for 10 seconds...");
        await Task.Delay(10000);

        await capture.PauseAsync();
        Console.WriteLine("Capture paused for 3 seconds...");
        await Task.Delay(3000);

        await capture.ResumeAsync();
        Console.WriteLine("Capture resumed for 5 more seconds...");
        await Task.Delay(5000);

        await capture.StopAsync();
        Console.WriteLine("Capture stopped.");
    }
}

