string GetSubtitleDescription(DVDSubPictureLangExt ext)
{
    return ext switch
    {
        DVDSubPictureLangExt.CaptionNormal => "Subtitles",
        DVDSubPictureLangExt.CCNormal => "Closed Captions",
        DVDSubPictureLangExt.CaptionBig => "Large Subtitles",
        DVDSubPictureLangExt.CaptionChildren => "Kids Subtitles",
        DVDSubPictureLangExt.Forced => "Forced Only",
        DVDSubPictureLangExt.DirectorCommentsNormal => "Commentary",
        _ => "Subtitles"
    };
}

// Analyzing DVD title information
void AnalyzeDVDTitle(DVDTitleInfo titleInfo)
{
