remarks.para:
The  class allows you to set a specific volume level
for a defined time period within an audio track. This is useful for creating ducking effects,
emphasizing or de-emphasizing certain portions of audio, or creating dynamic volume changes.

example.code:
// Example 1: Reduce volume during narration
var duckingEffect = new AudioVolumeEnvelopeEffect(30) // 30% volume
{
    StartTime = TimeSpan.FromSeconds(10),
    StopTime = TimeSpan.FromSeconds(25)
};

// Example 2: Create multiple volume levels
var effects = new[]
{
    new AudioVolumeEnvelopeEffect(100) { StartTime = TimeSpan.Zero, StopTime = TimeSpan.FromSeconds(5) },
    new AudioVolumeEnvelopeEffect(50) { StartTime = TimeSpan.FromSeconds(5), StopTime = TimeSpan.FromSeconds(10) },
    new AudioVolumeEnvelopeEffect(75) { StartTime = TimeSpan.FromSeconds(10), StopTime = TimeSpan.FromSeconds(15) }
};

// Example 3: Mute a section
var muteEffect = new AudioVolumeEnvelopeEffect(0) // Silence
{
    StartTime = TimeSpan.FromSeconds(30),
    StopTime = TimeSpan.FromSeconds(35)
};

// Different volume scenarios
var backgroundMusic = new AudioVolumeEnvelopeEffect(25);  // Quiet background
var normalVolume = new AudioVolumeEnvelopeEffect(100);   // Original volume
var emphasize = new AudioVolumeEnvelopeEffect(110);      // Slightly boosted (use carefully)

// Create effect for entire track
var fullTrackEffect = new AudioVolumeEnvelopeEffect(75);

// Create effect for specific time range
var timedEffect = new AudioVolumeEnvelopeEffect(50)
{
    StartTime = TimeSpan.FromSeconds(10),
    StopTime = TimeSpan.FromSeconds(20)
};

// Create ducking effect for background music
var duckingEffect = new AudioVolumeEnvelopeEffect(30)
{
    StartTime = TimeSpan.FromSeconds(5),
    StopTime = TimeSpan.FromSeconds(15)
};

// Example 1: Classic fade-in at track beginning
var fadeIn = new AudioVolumeFadeEffect(
    minLevel: 0,
    maxLevel: 100,
    fadeInDuration: TimeSpan.FromSeconds(3),
    fadeOutDuration: TimeSpan.Zero  // No fade-out
);

// Example 2: Fade-out at track end
var fadeOut = new AudioVolumeFadeEffect(
    minLevel: 0,
    maxLevel: 100,
    fadeInDuration: TimeSpan.Zero,  // No fade-in
    fadeOutDuration: TimeSpan.FromSeconds(5)
)
{
    StartTime = TimeSpan.FromMinutes(3),  // Start effect at 3 minutes
    StopTime = TimeSpan.FromMinutes(3.5)  // End at 3:30
};

// Example 3: Cross-fade effect (fade-in and fade-out)
var crossFade = new AudioVolumeFadeEffect(
    minLevel: 20,   // Don't fade to complete silence
    maxLevel: 100,
    fadeInDuration: TimeSpan.FromSeconds(2),
    fadeOutDuration: TimeSpan.FromSeconds(2)
)
{
    StartTime = TimeSpan.FromSeconds(10),
    StopTime = TimeSpan.FromSeconds(30)
};

// Quick fade-in
effect.FadeInDuration = TimeSpan.FromMilliseconds(500);

// Standard fade-in
effect.FadeInDuration = TimeSpan.FromSeconds(2);

// No fade-in (instant)
effect.FadeInDuration = TimeSpan.Zero;

// Standard fade-out
effect.FadeOutDuration = TimeSpan.FromSeconds(3);

// Quick fade-out for abrupt ending
effect.FadeOutDuration = TimeSpan.FromMilliseconds(200);

// No fade-out (instant cut)
effect.FadeOutDuration = TimeSpan.Zero;

// Standard fade-in/fade-out
var standardFade = new AudioVolumeFadeEffect(
    minLevel: 0,
    maxLevel: 100,
    fadeInDuration: TimeSpan.FromSeconds(2),
    fadeOutDuration: TimeSpan.FromSeconds(3)
);

// Fade between two audible levels
var partialFade = new AudioVolumeFadeEffect(
    minLevel: 30,   // Never below 30%
    maxLevel: 100,
    fadeInDuration: TimeSpan.FromSeconds(1),
    fadeOutDuration: TimeSpan.FromSeconds(1)
);

// Fade-in only (no fade-out)
var fadeInOnly = new AudioVolumeFadeEffect(
    minLevel: 0,
    maxLevel: 100,
    fadeInDuration: TimeSpan.FromSeconds(3),
    fadeOutDuration: TimeSpan.Zero
);

