// Subscribe to VU meter events
mediaPlayer.OnVUMeterData += (sender, e) =>
{
    // Process stereo audio levels
    if (e.MeterData.Length >= 2)
    {
        int leftChannel = e.MeterData[0];
        int rightChannel = e.MeterData[1];

        // Update UI level meters
        UpdateLevelMeter(leftChannel, rightChannel);
    }
};

// Subscribe to FFT events for spectrum analysis
audioProcessor.OnFFTData += (sender, e) =>
{
    // Calculate magnitude spectrum
    double[] magnitudes = new double[e.Result.Length / 2];

    for (int i = 0; i < magnitudes.Length; i++)
    {
        // Calculate magnitude from complex number
        double real = e.Result[i].X;
        double imaginary = e.Result[i].Y;
        magnitudes[i] = Math.Sqrt(real * real + imaginary * imaginary);

        // Convert to decibels
        double db = 20 * Math.Log10(magnitudes[i]);
    }

    // Update spectrum display
    UpdateSpectrumVisualizer(magnitudes);
};

remarks.para:
To convert to decibels (dBFS):

float dBFS = 20.0f * (float)Math.Log10(Math.Abs(MaxSample));

Where 0 dBFS corresponds to a sample value of 1.0.

The absolute value of MinSample can be used together with MaxSample to determine
the overall peak level:

float peakLevel = Math.Max(Math.Abs(MinSample), Math.Abs(MaxSample));

example.code:
// Example of handling a WindowCapture event:
void OnWindowDetected(object sender, WindowCaptureEventArgs e)
{
