// Example of creating a YouTubeVideoInfo object:
var videoInfo = new YouTubeVideoInfo(
    "https://example.com/video_stream_url", 
    YouTubeVideoInfoFormat.Mp4,
    1080);

Console.WriteLine($"Video URI: {videoInfo.Uri}");
Console.WriteLine($"Resolution: {videoInfo.Resolution}p");
Console.WriteLine($"Format: {videoInfo.Format}");

// Example of handling a YouTubeVideoPlayback event:
void OnYouTubeVideoFormatsDetected(object sender, YouTubeVideoPlaybackEventArgs e)
{
    Console.WriteLine($"Found {e.Formats.Count} available formats.");
    foreach (var format in e.Formats)
    {
        Console.WriteLine($"  - {format.Resolution}p ({format.Format})");
    }

    // Select the highest resolution available
    e.SelectedFormatIndex = e.Formats.OrderByDescending(f => f.Resolution).ThenBy(f => f.Format.ToString()).ToList().IndexOf(e.Formats.OrderByDescending(f => f.Resolution).ThenBy(f => f.Format.ToString()).First());
    Console.WriteLine($"Selected format index: {e.SelectedFormatIndex}");
}

member.returns:
A task that represents the asynchronous operation. The task result contains
true if the videos are considered identical (difference below threshold);
otherwise, false.

member.remarks:
This method performs direct image comparison without temporal analysis.
Both images must be in RGB24 format. The images can have different dimensions;
the comparison algorithm will handle the scaling internally.

